const CODE_BODY = (recovery) => `<div dir="ltr" lang="en" class="admin-login text-left text-slate-950 dark:text-white"><main class="admin-login__shell admin-login__shell--compact"><section class="admin-login__form-panel p-6 sm:p-9">${BRAND_MARK()}<p class="text-xs font-bold uppercase tracking-[.18em] text-indigo-600">Secure administration</p><h1 class="mt-2 text-3xl font-black tracking-tight">Verify your sign-in</h1><p id="admin-code-help" class="mt-2 text-sm leading-6 text-slate-600 dark:text-slate-300">${recovery ? 'Enter one saved recovery code. It works once. This step expires after five minutes.' : 'Enter the six-digit code from your authenticator app. This step expires after five minutes.'}</p><form class="mt-6 space-y-5" aria-busy="false"><div class="admin-login__field"><label for="admin-auth-code" class="text-sm font-bold text-slate-700 dark:text-slate-200">${recovery ? 'Recovery code' : 'Authenticator code'}</label><input id="admin-auth-code" required="" inputmode="${recovery ? 'text' : 'numeric'}" pattern="${recovery ? '[A-Fa-f0-9-]{20,23}' : '[0-9]{6}'}" maxlength="${recovery ? 23 : 6}" autocomplete="${recovery ? 'off' : 'one-time-code'}" dir="ltr" lang="en" aria-describedby="admin-code-help" class="admin-login__input w-full rounded-xl border border-slate-300 bg-white px-4 py-3 text-center text-xl font-bold tracking-[.3em] text-slate-950 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 dark:border-slate-600 dark:bg-slate-800 dark:text-white" type="text" value=""></div><button disabled="" class="w-full rounded-xl bg-indigo-600 py-3.5 text-sm font-extrabold text-white transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-50">Verify code</button></form><button type="button" class="mt-3 w-full py-2 text-sm font-bold text-indigo-600 hover:underline dark:text-indigo-300">${recovery ? 'Use authenticator app instead' : 'Use a recovery code'}</button><button type="button" class="mt-4 w-full rounded-xl border border-slate-200 py-3 text-sm font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300 dark:hover:bg-slate-800">Back to sign in</button></section></main></div>`
export const CODE = CODE_BODY(false)
